        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long d = (long) in.nval;
        long[] nums = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (long) in.nval;
        }
        List<List<Long>> res = findProgressions(nums, d);
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append('\n');
        for (List<Long> seq : res) {
            for (int i = 0; i < seq.size(); i++) sb.append(seq.get(i)).append(i + 1 < seq.size() ? " " : "\n");
        }
        System.out.print(sb);
    }
}
